
    (()=>{
      document.querySelectorAll('.comparison-frame').forEach((comparison)=>{
        const comparisonRange=comparison.querySelector('.comparison-range');
        if(!comparisonRange)return;
        function updateComparison(){const value=Number(comparisonRange.value);comparison.style.setProperty('--split',value+'%');comparisonRange.setAttribute('aria-valuetext',value+'% da imagem antes visível')}
        updateComparison();
        comparisonRange.addEventListener('input',updateComparison);
        let comparisonPointer=null;
        function positionComparison(event){const rect=comparison.getBoundingClientRect();comparisonRange.value=String(Math.round(Math.max(0,Math.min(100,(event.clientX-rect.left)/rect.width*100))));updateComparison()}
        comparisonRange.addEventListener('pointerdown',event=>{if(!event.isPrimary||event.button!==0)return;event.preventDefault();comparisonPointer=event.pointerId;comparisonRange.focus({preventScroll:true});comparisonRange.setPointerCapture(event.pointerId);positionComparison(event)});
        comparisonRange.addEventListener('pointermove',event=>{if(event.pointerId===comparisonPointer)positionComparison(event)});
        ['pointerup','pointercancel','lostpointercapture'].forEach(type=>comparisonRange.addEventListener(type,()=>{comparisonPointer=null}));
      });
      const WA_NUMBER='5547997958262';
      const directWA='https://wa.me/'+WA_NUMBER+'?text='+encodeURIComponent('Olá, vim pelo site da Exclusive PPF & Detail e gostaria de solicitar uma avaliação para o meu carro.');
      const evaluationModal=document.querySelector('.evaluation-modal');
      const evaluationDialog=evaluationModal.querySelector('.evaluation-dialog');
      const evaluationForm=evaluationModal.querySelector('.evaluation-form');
      const evaluationName=evaluationModal.querySelector('.evaluation-name');
      const evaluationError=evaluationModal.querySelector('.evaluation-error');
      const evaluationClose=evaluationModal.querySelector('.evaluation-close');
      const evaluationVideo=evaluationModal.querySelector('.evaluation-video');
      const evaluationServiceButtons=[...evaluationModal.querySelectorAll('.evaluation-service')];
      const siteShellForLead=document.querySelector('.site-shell');
      let evaluationService='Quero uma avaliação';
      let evaluationLastFocus=null;

      function openEvaluationModal(trigger){
        evaluationLastFocus=trigger||document.activeElement;
        evaluationError.textContent='';
        evaluationModal.classList.add('open');
        evaluationModal.setAttribute('aria-hidden','false');
        siteShellForLead.inert=true;
        document.body.classList.add('lock');
        try{
          if(evaluationVideo.readyState>=1){
            evaluationVideo.currentTime=6;
          }else{
            evaluationVideo.addEventListener('loadedmetadata',()=>{evaluationVideo.currentTime=6},{once:true});
          }
        }catch(_){}
        evaluationVideo.play().catch(()=>{});
        requestAnimationFrame(()=>evaluationName.focus());
      }

      function closeEvaluationModal(){
        evaluationModal.classList.remove('open');
        evaluationModal.setAttribute('aria-hidden','true');
        siteShellForLead.inert=false;
        document.body.classList.remove('lock');
        evaluationVideo.pause();
        if(evaluationLastFocus) evaluationLastFocus.focus();
      }

      document.querySelectorAll('.wa-link').forEach(a=>{
        if(a.classList.contains('btn')){
          a.href='#';
          a.removeAttribute('target');
          a.removeAttribute('rel');
          a.addEventListener('click',e=>{
            e.preventDefault();
            openEvaluationModal(a);
          });
        }else{
          a.href=directWA;
          a.target='_blank';
          a.rel='noopener';
        }
      });

      evaluationClose.addEventListener('click',closeEvaluationModal);
      evaluationModal.addEventListener('click',e=>{if(e.target===evaluationModal)closeEvaluationModal()});
      evaluationDialog.addEventListener('click',e=>e.stopPropagation());

      evaluationServiceButtons.forEach(button=>{
        button.setAttribute('aria-pressed',String(button.classList.contains('active')));
        button.addEventListener('click',()=>{
          evaluationService=button.dataset.service||'Quero uma avaliação';
          evaluationServiceButtons.forEach(item=>{
            const active=item===button;
            item.classList.toggle('active',active);
            item.setAttribute('aria-pressed',String(active));
          });
        });
      });

      evaluationForm.addEventListener('submit',e=>{
        e.preventDefault();
        const name=evaluationName.value.trim().replace(/\s+/g,' ');
        if(name.length<2){
          evaluationError.textContent='Digite seu nome para continuar.';
          evaluationName.focus();
          return;
        }
        evaluationError.textContent='';
        const serviceText=evaluationService==='Quero uma avaliação'
          ? 'gostaria de solicitar uma avaliação para entender qual serviço é o mais indicado para o meu carro'
          : `tenho interesse em ${evaluationService} e gostaria de solicitar uma avaliação para o meu carro`;
        const message=`Olá, meu nome é ${name}. Vim pelo site da Exclusive PPF & Detail e ${serviceText}.`;
        const url='https://wa.me/'+WA_NUMBER+'?text='+encodeURIComponent(message);
        window.open(url,'_blank','noopener');
        closeEvaluationModal();
      });

      const menu=document.querySelector('.mobile-menu'),toggle=document.querySelector('.menu-toggle'),closeMenu=document.querySelector('.menu-close');
      function setMenu(open){menu.classList.toggle('open',open);menu.setAttribute('aria-hidden',String(!open));toggle.setAttribute('aria-expanded',String(open));document.body.classList.toggle('lock',open)}
      toggle.addEventListener('click',()=>setMenu(true));closeMenu.addEventListener('click',()=>setMenu(false));menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));

      const galleries={
        pickup:{title:'Ford F-75',subtitle:'Clássico preservado nos detalhes',images:['data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,']},
        m2:{title:'Ferrari',subtitle:'Performance tratada como projeto',images:['data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,']},
        urus:{title:'Mercedes-AMG G 63',subtitle:'Presença, acabamento e proteção',images:['data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,']},
        x1:{title:'Ford Mustang GT',subtitle:'Personalidade em cada detalhe',images:['data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,']}
      };
      const modal=document.querySelector('.gallery'),track=modal.querySelector('.gallery-track'),thumbs=modal.querySelector('.gallery-thumbs'),metaTitle=modal.querySelector('strong'),metaSub=modal.querySelector('.gallery-meta span'),shell=document.querySelector('.site-shell');let active=null,index=0,lastFocus=null;
      metaSub.setAttribute('aria-live','polite');
      function render(){const data=galleries[active];metaTitle.textContent=data.title;metaSub.textContent=`Foto ${index+1} de ${data.images.length} — ${data.subtitle}`;thumbs.querySelectorAll('.thumb').forEach((t,i)=>{t.classList.toggle('active',i===index);t.setAttribute('aria-current',String(i===index))})}
      function goTo(i){index=i;track.scrollTo({left:i*track.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});render()}
      function openGallery(key){active=key;index=0;lastFocus=document.activeElement;thumbs.replaceChildren();track.replaceChildren();galleries[key].images.forEach((src,i)=>{const slide=document.createElement('figure');slide.className='gallery-slide';const img=document.createElement('img');img.src=src;img.alt=`${galleries[key].title} — foto ${i+1}`;img.decoding='async';img.loading=i===0?'eager':'lazy';img.draggable=false;slide.appendChild(img);track.appendChild(slide);const b=document.createElement('button');b.className='thumb';b.type='button';b.setAttribute('aria-label',`Ver foto ${i+1}`);const mini=img.cloneNode();mini.alt='';mini.loading='lazy';b.appendChild(mini);b.addEventListener('click',()=>goTo(i));thumbs.appendChild(b)});render();modal.classList.add('open');modal.setAttribute('aria-hidden','false');shell.inert=true;document.body.classList.add('lock');track.scrollTo({left:0,behavior:'instant'});modal.querySelector('.gallery-close').focus()}
      function closeGallery(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');shell.inert=false;document.body.classList.remove('lock');if(lastFocus)lastFocus.focus()}
      function move(dir){const len=galleries[active].images.length;goTo((index+dir+len)%len)}
      track.addEventListener('scroll',()=>{if(!active||!track.clientWidth)return;const next=Math.round(track.scrollLeft/track.clientWidth);if(next!==index){index=next;render()}},{passive:true});
      window.addEventListener('resize',()=>{if(modal.classList.contains('open'))track.scrollTo({left:index*track.clientWidth,behavior:'instant'})});
      document.querySelectorAll('[data-gallery]').forEach(b=>b.addEventListener('click',()=>openGallery(b.dataset.gallery)));document.querySelector('[data-open-first]').addEventListener('click',()=>openGallery('m2'));
      modal.querySelector('.gallery-close').addEventListener('click',closeGallery);modal.querySelector('.gallery-prev').addEventListener('click',()=>move(-1));modal.querySelector('.gallery-next').addEventListener('click',()=>move(1));modal.addEventListener('click',e=>{if(e.target===modal)closeGallery()});
      document.addEventListener('keydown',e=>{
        if(evaluationModal.classList.contains('open')){
          if(e.key==='Escape'){e.preventDefault();closeEvaluationModal();return}
          if(e.key==='Tab'){
            const focusable=[...evaluationModal.querySelectorAll('button,input,[href],[tabindex]:not([tabindex="-1"])')].filter(el=>!el.disabled);
            const first=focusable[0],last=focusable[focusable.length-1];
            if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
            else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
          }
          return;
        }
        if(menu.classList.contains('open')&&e.key==='Escape')setMenu(false);
        if(!modal.classList.contains('open'))return;
        if(e.key==='Escape')closeGallery();
        if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}
        if(e.key==='ArrowRight'){e.preventDefault();move(1)}
        if(e.key==='Tab'){
          const focusable=[...modal.querySelectorAll('button,[tabindex="0"]')];
          const first=focusable[0],last=focusable[focusable.length-1];
          if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
          else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
        }
      });

      if('IntersectionObserver'in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>io.observe(el))}else document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'));
    })();
  